# Generated by Descant: acceptance tests.

# frozen_string_literal: true

require "spec_helper"
require_relative "../../../../spec/support/timekeeping/fake_relay"

RSpec.describe TimekeepingRelay::Relay do
  it "survives duplicates: a same-key replay after a lost mark changes nothing and a resent row in a new batch is counted ignored" do
    timekeeping = TimekeepingContract::FakeTimekeeping.new
    credential = timekeeping.add_service(company_id: nil, name: "timekeeping", operations: ["deliver"])
    fake_relay = TimekeepingContract::FakeRelay.new(source: timekeeping)
    generation = TimekeepingContract::FakeTimekeeping::INITIAL_GENERATION
    first_row = { "generation" => generation, "outbox_position" => 1, "entry" => { "id" => 10, "company_id" => 1, "version" => 1 } }
    second_row = { "generation" => generation, "outbox_position" => 2, "entry" => { "id" => 11, "company_id" => 1, "version" => 1 } }

    source_class = Class.new do
      attr_reader :sent
      attr_accessor :fail_next_mark

      def initialize(rows)
        @rows = rows
        @sent = []
      end

      def unsent_after(position, limit)
        @rows.reject { |row| @sent.include?(row["outbox_position"]) || row["outbox_position"] <= position }
             .sort_by { |row| row["outbox_position"] }.first(limit)
      end

      def mark_sent(positions)
        if fail_next_mark
          self.fail_next_mark = false
          raise "outbox database went away"
        end
        @sent |= positions
        nil
      end
    end

    answers = []
    endpoint = Object.new
    endpoint.define_singleton_method(:deliver) do |batch, idempotency_key:|
      response = fake_relay.call("POST", "/internal/v1/timekeeping/entry-snapshots",
                                 headers: { "Authorization" => "Bearer #{credential}", "Idempotency-Key" => idempotency_key },
                                 body: batch)
      answers << response.body
      TimekeepingRelay::Response.new(status: response.status, body: response.body)
    end

    source = source_class.new([first_row])
    source.fail_next_mark = true
    relay = described_class.new(source: source, endpoint: endpoint)
    begin
      relay.deliver(limit: 10)
    rescue StandardError
      nil
    end
    expect(source.sent).to eq([])
    projected = fake_relay.projected_entry(10)

    # "The relay marks a row sent only after a `200`, so delivery is at least once."
    expect(relay.deliver(limit: 10)).to eq(sent: 1, last_position: 1)
    expect(answers.size).to eq(2)
    expect(answers.last).to eq(answers.first)
    expect(fake_relay.projected_entry(10)).to eq(projected)
    expect(source.sent).to eq([1])

    resending_source = source_class.new([first_row, second_row])
    expect(described_class.new(source: resending_source, endpoint: endpoint).deliver(limit: 10)).to eq(sent: 2, last_position: 2)
    expect(answers.last).to eq("applied" => 1, "ignored" => 1)
    expect(fake_relay.projected_entry(10)).to eq(projected)
  end
end
